use serde::Deserialize;
use std::sync::OnceLock;

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CommandDefinition {
    pub id: String,
    pub label: String,
    pub description: String,
    pub group: String,
    pub order: usize,
    pub search_terms: Vec<String>,
    pub keywords: Vec<String>,
    pub shortcut: Option<String>,
    pub keybinding: Option<String>,
}

pub fn commands() -> &'static [CommandDefinition] {
    static COMMANDS: OnceLock<Vec<CommandDefinition>> = OnceLock::new();
    COMMANDS.get_or_init(|| {
        // Generated by running the actual Source registry with a collapsed,
        // editable selection; selection-only commands are correctly absent.
        let mut catalog: Vec<CommandDefinition> = serde_json::from_str(include_str!(
            "../../fixtures/insert-menu/source-catalog.json"
        ))
        .expect("checked-in Source insert catalog");
        // Explicitly requested native addition; currently absent from Source's
        // slash registry, so parity checks compare the Source subset separately.
        catalog.push(CommandDefinition {
            id: "insert.link".into(),
            label: "Link".into(),
            description: "Insert a link into the manuscript.".into(),
            group: "Insert".into(),
            order: 15,
            search_terms: vec!["hyperlink".into(), "url".into(), "href".into()],
            keywords: vec!["link".into(), "url".into()],
            shortcut: None,
            keybinding: None,
        });
        catalog
    })
}

#[derive(Clone, Copy, Debug)]
pub struct Candidate {
    pub command: &'static CommandDefinition,
    pub score: i32,
}

pub fn candidates(query: &str) -> Vec<Candidate> {
    let mut results = commands()
        .iter()
        .filter_map(|command| {
            let mut fields = vec![
                command.label.as_str(),
                command.description.as_str(),
                command.id.as_str(),
            ];
            fields.extend(command.search_terms.iter().map(String::as_str));
            fields.extend(command.keywords.iter().map(String::as_str));
            super::filter::score(&command.label, &fields.join(" "), query)
                .map(|score| Candidate { command, score })
        })
        .collect::<Vec<_>>();
    results.sort_by(|a, b| {
        b.score
            .cmp(&a.score)
            .then_with(|| a.command.group.cmp(&b.command.group))
            .then_with(|| a.command.order.cmp(&b.command.order))
    });
    results
}
